create or replace function public.admin_can_project(_p uuid) returns boolean language sql stable security definer set search_path to 'public' as $$ select public.is_admin() and exists (select 1 from public.projects p where p.id=_p and public.is_org_member(p.buyer_org_id)) $$; create or replace function public.admin_can_org(_o uuid) returns boolean language sql stable security definer set search_path to 'public' as $$ select public.is_admin() and (public.is_org_member(_o) or exists (select 1 from public.applications a join public.projects p on p.id=a.project_id where a.organization_id=_o and a.status<>'draft' and public.is_org_member(p.buyer_org_id)) or exists (select 1 from public.project_invites i join public.projects p on p.id=i.project_id where i.organization_id=_o and public.is_org_member(p.buyer_org_id))) $$; create or replace function public.admin_can_app(_a uuid) returns boolean language sql stable security definer set search_path to 'public' as $$ select public.is_admin() and exists (select 1 from public.applications a where a.id=_a and a.status<>'draft' and public.admin_can_project(a.project_id)) $$; create or replace function public.admin_can_user(_u uuid) returns boolean language sql stable security definer set search_path to 'public' as $$ select public.is_admin() and (_u=auth.uid() or exists (select 1 from public.memberships m where m.user_id=_u and public.admin_can_org(m.organization_id))) $$; create or replace function public.notify_project_admins(_project uuid,_kind text,_title text,_body text,_link text) returns void language sql security definer set search_path to 'public' as $$ insert into public.notifications(user_id,kind,title,body,link) select m.user_id,_kind,_title,_body,_link from public.projects p join public.memberships m on m.organization_id=p.buyer_org_id join public.user_roles r on r.user_id=m.user_id and r.role='admin' where p.id=_project $$;
begin;
drop policy "ad: own or admin read" on public.application_documents; create policy "ad: own or admin read" on public.application_documents for select to authenticated using (exists (select 1 from public.applications a where a.id=application_documents.application_id and (public.is_org_member(a.organization_id) or public.admin_can_app(a.id))));
drop policy "apps: own or admin read" on public.applications; create policy "apps: own or admin read" on public.applications for select to authenticated using (public.is_org_member(organization_id) or public.admin_can_app(id));
drop policy "audit: admin read" on public.audit_events; create policy "audit: admin read" on public.audit_events for select to authenticated using (public.is_admin() and (public.is_org_member(organization_id) or public.admin_can_org(organization_id)));
drop policy "awards: admin or winner read" on public.awards; create policy "awards: admin or winner read" on public.awards for select to authenticated using (public.admin_can_project(project_id) or exists (select 1 from public.applications a where a.id=awards.application_id and public.is_org_member(a.organization_id)));
drop policy "cp: own or admin read" on public.contractor_profiles; create policy "cp: own or admin read" on public.contractor_profiles for select to authenticated using (public.is_org_member(organization_id) or public.admin_can_org(organization_id));
drop policy "dv: own or admin read" on public.document_versions; create policy "dv: own or admin read" on public.document_versions for select to authenticated using (public.is_org_member(organization_id) or public.admin_can_org(organization_id));
drop policy "docs: own or admin update" on public.documents; create policy "docs: own or admin update" on public.documents for update to authenticated using (public.is_org_member(organization_id) or public.admin_can_org(organization_id)) with check (public.is_org_member(organization_id) or public.admin_can_org(organization_id));
drop policy "docs: own or admin read" on public.documents; create policy "docs: own or admin read" on public.documents for select to authenticated using (public.is_org_member(organization_id) or public.admin_can_org(organization_id));
drop policy "inv: admin read" on public.invitations; create policy "inv: admin read" on public.invitations for select to authenticated using (public.is_admin() and created_by=auth.uid());
drop policy "inv: admin update" on public.invitations; create policy "inv: admin update" on public.invitations for update to authenticated using (public.is_admin() and created_by=auth.uid()) with check (public.is_admin() and created_by=auth.uid());
drop policy "inv: admin insert" on public.invitations; create policy "inv: admin insert" on public.invitations for insert to authenticated with check (public.is_admin() and created_by=auth.uid());
drop policy "memberships: self or admin read" on public.memberships; create policy "memberships: self or admin read" on public.memberships for select to authenticated using (user_id=auth.uid() or public.admin_can_user(user_id));
drop policy "mob: admin all" on public.mobilisation_items; create policy "mob: admin all" on public.mobilisation_items for all to authenticated using (public.admin_can_org(organization_id)) with check (public.admin_can_org(organization_id));
drop policy "orgs: admin update" on public.organizations; create policy "orgs: admin update" on public.organizations for update to authenticated using (public.admin_can_org(id)) with check (public.admin_can_org(id));
drop policy "orgs: admin all read" on public.organizations; create policy "orgs: admin all read" on public.organizations for select to authenticated using (public.admin_can_org(id) or exists (select 1 from public.memberships m where m.user_id=auth.uid() and m.organization_id=organizations.id));
drop policy "profiles: self or admin read" on public.profiles; create policy "profiles: self or admin read" on public.profiles for select to authenticated using (id=auth.uid() or public.admin_can_user(id));
drop policy "invites: admin insert" on public.project_invites; create policy "invites: admin insert" on public.project_invites for insert to authenticated with check (public.admin_can_project(project_id));
drop policy "invites: admin delete" on public.project_invites; create policy "invites: admin delete" on public.project_invites for delete to authenticated using (public.admin_can_project(project_id));
drop policy "invites: admin or own read" on public.project_invites; create policy "invites: admin or own read" on public.project_invites for select to authenticated using (public.admin_can_project(project_id) or public.is_org_member(organization_id));
drop policy "req: admin insert" on public.project_requirements; create policy "req: admin insert" on public.project_requirements for insert to authenticated with check (public.admin_can_project(project_id));
drop policy "req: admin update" on public.project_requirements; create policy "req: admin update" on public.project_requirements for update to authenticated using (public.admin_can_project(project_id)) with check (public.admin_can_project(project_id));
drop policy "projects: admin insert" on public.projects; create policy "projects: admin insert" on public.projects for insert to authenticated with check (public.is_admin() and public.is_org_member(buyer_org_id));
drop policy "projects: admin update" on public.projects; create policy "projects: admin update" on public.projects for update to authenticated using (public.admin_can_project(id)) with check (public.admin_can_project(id));
drop policy "projects: admin delete drafts" on public.projects; create policy "projects: admin delete drafts" on public.projects for delete to authenticated using (public.admin_can_project(id) and status='draft');
drop policy "reviews: admin read" on public.reviews; create policy "reviews: admin read" on public.reviews for select to authenticated using (public.admin_can_app(application_id));
drop policy "reviews: admin insert" on public.reviews; create policy "reviews: admin insert" on public.reviews for insert to authenticated with check (public.admin_can_app(application_id) and reviewer_id=auth.uid());
drop policy "roles: self or admin read" on public.user_roles; create policy "roles: self or admin read" on public.user_roles for select to authenticated using (user_id=auth.uid());
drop policy "docs storage: member read" on storage.objects; create policy "docs storage: member read" on storage.objects for select to authenticated using (bucket_id='documents' and (public.admin_can_org((storage.foldername(name))[1]::uuid) or public.is_org_member((storage.foldername(name))[1]::uuid)));
commit;
do $$ declare r record; d text; d2 text; begin for r in select p.oid, p.proname from pg_proc p where p.pronamespace='public'::regnamespace and p.proname in ('award_application','set_application_status','set_contractor_status','start_mobilisation','submit_application','can_view_project') loop d:=pg_get_functiondef(r.oid); d2:=d; if r.proname in ('award_application','set_application_status','start_mobilisation') then d2:=regexp_replace(d,'IF NOT (public[.])?is_admin[(][)] THEN','IF NOT public.admin_can_app(_app) THEN'); elsif r.proname='set_contractor_status' then d2:=regexp_replace(d,'IF NOT (public[.])?is_admin[(][)] THEN','IF NOT public.admin_can_org(_org) THEN'); elsif r.proname='submit_application' then d2:=regexp_replace(d,'(public[.])?notify_admins[(]''submission'',','public.notify_project_admins(a.project_id,''submission'','); elsif r.proname='can_view_project' then d2:=regexp_replace(d,'SELECT (public[.])?is_admin[(][)] OR','SELECT public.admin_can_project(_project) OR'); end if; if d2=d then raise exception 'no change %', r.proname; end if; execute d2; end loop; end $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path to 'public' as $f$ declare inv public.invitations; org_id uuid; v_code text; v_company text; v_hp text; v_type text; begin insert into public.profiles(id,full_name,email,phone) values (new.id,new.raw_user_meta_data->>'full_name',new.email,new.raw_user_meta_data->>'phone'); v_hp:=coalesce(new.raw_user_meta_data->>'website',''); if v_hp<>'' then raise exception 'Registration rejected'; end if; v_type:=lower(trim(coalesce(new.raw_user_meta_data->>'account_type','contractor'))); v_company:=trim(coalesce(new.raw_user_meta_data->>'company_name','')); if v_type='buyer' then if char_length(v_company)<2 or char_length(v_company)>120 then raise exception 'Enter your company name (2 to 120 characters)'; end if; insert into public.organizations(name,kind) values (v_company,'buyer') returning id into org_id; insert into public.memberships(user_id,organization_id) values (new.id,org_id); insert into public.user_roles(user_id,role) values (new.id,'admin'); return new; end if; v_code:=upper(trim(coalesce(new.raw_user_meta_data->>'invite_code',''))); if v_code<>'' then select * into inv from public.invitations i where i.code=v_code and i.status='pending' and i.expires_at>now() and lower(i.email)=lower(new.email) limit 1; if inv.id is null then raise exception 'That invitation code does not match this email address or has expired'; end if; v_company:=inv.organization_name; elsif char_length(v_company)<2 or char_length(v_company)>120 then raise exception 'Enter your company name (2 to 120 characters)'; end if; insert into public.organizations(name,kind) values (v_company,'contractor') returning id into org_id; insert into public.memberships(user_id,organization_id) values (new.id,org_id); insert into public.user_roles(user_id,role) values (new.id,'contractor'); insert into public.contractor_profiles(organization_id,contact_name,contact_email,contact_phone) values (org_id,new.raw_user_meta_data->>'full_name',new.email,new.raw_user_meta_data->>'phone'); if inv.id is not null then update public.invitations set status='accepted', accepted_org_id=org_id where id=inv.id; end if; return new; end $f$;
create policy "projects: buyer admin read" on public.projects for select to authenticated using (public.is_admin() and public.is_org_member(buyer_org_id));
